import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        for (int g = 1; g <= t; g++) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            List<List<Integer>> adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
            int[] indegree = new int[n];
            for (int i = 0; i < m; i++) {
                int before = sc.nextInt();
                int after = sc.nextInt();
                adj.get(before).add(after);
                indegree[after]++;
            }
            List<Integer> order = topoOrder(n, adj, indegree);
            if (order.size() == n) {
                System.out.println("Graph " + g + ": order " + order);
            } else {
                System.out.println("Graph " + g + ": cycle, " + (n - order.size()) + " stuck");
            }
        }
    }

    static List<Integer> topoOrder(int n, List<List<Integer>> adj, int[] indegree) {
        Queue<Integer> ready = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                ready.offer(i);
            }
        }
        List<Integer> order = new ArrayList<>();
        while (!ready.isEmpty()) {
            int node = ready.poll();
            order.add(node);
            for (int next : adj.get(node)) {
                indegree[next]--;
                if (indegree[next] == 0) {
                    ready.offer(next);
                }
            }
        }
        return order;
    }
}

